// ===== HIER ANPASSEN (der einzige Ort je Workflow) =====
const cfg = {
  supabaseUrl:  'https://DEIN-AGENCY-REF.supabase.co',
  auditorUrl:   'https://DEIN-N8N/webhook/agency-auditor',
  freigabeUrl:  'https://DEIN-N8N/webhook/agency-freigabe',
  kennzahlenUrl:'https://www.myimmoapp.de/api/intern/kennzahlen',
  mailAn:       'DEINE@MAIL.DE',
  mailVon:      'agency@myimmoapp.de',
  mailVonName:  'MyImmo Agency',
  githubRepo:   'jxnashap/myimmo-app',
};
// =======================================================

// Eingang aus dem Webhook: { titel, ziel, rolle, risiko?, kontext? }
const eingang = $input.first().json.body ?? {};
if (!eingang.titel || !eingang.ziel || !eingang.rolle) {
  throw new Error('Pflichtfelder fehlen: titel, ziel, rolle');
}
return [{ json: { ...cfg, eingang } }];

// Der Deckel warnt nicht, er stoppt (Verfassung, Abschnitt Finanzdisziplin).
const v = $input.first().json;
return [{ json: { ok: false, gestoppt: true, grund: v.fehler || 'Budget erschöpft',
  ausgaben_usd: v.ausgaben_usd ?? null, deckel_usd: v.deckel_usd ?? null } }];

const v = $('Vorgang anlegen').first().json;
const e = $('Konfiguration').first().json.eingang;

const auftrag = [
  'VORGANG #' + v.nr,
  'TITEL: ' + e.titel,
  'ZIEL: ' + e.ziel,
  'RISIKOSTUFE: ' + v.risiko,
  e.kontext ? 'KONTEXT:\n' + e.kontext : null,
].filter(Boolean).join('\n\n');

return [{ json: { anfrage: {
  model: v.rolle.modell,
  max_tokens: v.rolle.max_tokens,
  system: v.rolle.prompt,
  thinking: { type: 'adaptive' },
  output_config: { effort: v.rolle.effort },
  messages: [{ role: 'user', content: auftrag }],
} } }];

const r = $input.first().json;
if (r.stop_reason === 'refusal') {
  throw new Error('Modell hat die Anfrage abgelehnt (stop_reason=refusal).');
}
const text = (r.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n\n');
return [{ json: {
  text,
  stop_reason: r.stop_reason ?? null,
  abgeschnitten: r.stop_reason === 'max_tokens',
  tokens_ein: r.usage?.input_tokens ?? 0,
  tokens_aus: r.usage?.output_tokens ?? 0,
  tokens_cache: r.usage?.cache_read_input_tokens ?? 0,
} }];

const v   = $('Vorgang anlegen').first().json;
const cfg = $('Konfiguration').first().json;
const erg = $('Ergebnis lesen').first().json;
const buch= $('Lauf buchen').first().json;
const aud = $input.first().json;

const urteil = aud.urteil ?? 'PASS';
const freigabeNoetig = v.freigabe_pflicht && urteil === 'PASS';

// FAIL beendet den Vorgang — die Datenbank hat den Status bereits gesetzt.
const status = urteil === 'FAIL' ? 'gestoppt'
             : freigabeNoetig    ? 'wartet_auf_freigabe'
             :                     'fertig';

const link = (e) => cfg.freigabeUrl + '?vorgang=' + v.vorgang_id
           + '&token=' + v.freigabe_token + '&entscheidung=' + e;

const kopf = [
  'Vorgang #' + v.nr + ' · ' + cfg.eingang.titel,
  'Rolle: ' + v.rolle.name + ' (' + v.rolle.modell + ') · Risiko: ' + v.risiko,
  'Audit: ' + urteil + (aud.uebersprungen ? ' (nicht erforderlich)' : ''),
  'Kosten: ' + (buch.kosten_usd ?? '?') + ' USD · Monat: ' + (buch.ausgaben_monat_usd ?? '?')
    + ' von ' + (buch.deckel_usd ?? '?') + ' USD',
].join('\n');

const auditBlock = aud.uebersprungen ? '' : [
  '', '--- AUDIT ---',
  'Urteil: ' + urteil,
  aud.befund ? 'Befund: ' + aud.befund : null,
  aud.fehlende_evidenz ? 'Fehlende Evidenz: ' + aud.fehlende_evidenz : null,
  aud.billigstes_experiment ? 'Billigstes Experiment: ' + aud.billigstes_experiment : null,
].filter(x => x !== null).join('\n');

const htmlText = (s) => String(s)
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

const knoepfe = freigabeNoetig
  ? '<p><a href="' + link('ja') + '" style="background:#D4A847;color:#0F0F0E;padding:10px 18px;'
    + 'border-radius:18px;text-decoration:none;font-weight:600">Freigeben</a>'
    + '&nbsp;&nbsp;<a href="' + link('nein') + '" style="padding:10px 18px;border-radius:18px;'
    + 'border:1px solid #e5e5e5;text-decoration:none;color:#0F0F0E">Ablehnen</a></p>'
  : '';

const html = '<div style="font-family:system-ui,sans-serif;max-width:680px">'
  + '<pre style="white-space:pre-wrap;font:inherit">' + htmlText(kopf) + '</pre>'
  + knoepfe
  + '<hr style="border:0;border-top:1px solid #e5e5e5">'
  + '<pre style="white-space:pre-wrap;font:inherit">' + htmlText(erg.text) + '</pre>'
  + (auditBlock ? '<pre style="white-space:pre-wrap;font:inherit;color:#666">'
      + htmlText(auditBlock) + '</pre>' : '')
  + '</div>';

return [{ json: {
  vorgang_id: v.vorgang_id, nr: v.nr, status, urteil,
  freigabe_noetig: freigabeNoetig,
  abgeschnitten: erg.abgeschnitten,
  kosten_usd: buch.kosten_usd ?? null,
  budget_rest_usd: buch.budget_rest_usd ?? null,
  betreff: '[Agency #' + v.nr + '] ' + cfg.eingang.titel + ' — ' + status,
  html, text: erg.text,
} }];
